// Preconfigured Gravity UI setup is ALREADY wired here (both CSS imports + ThemeProvider).
// Implement the requested feature in App.tsx (you may add sibling files).
import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React from 'react';
import ReactDOM from 'react-dom/client';
import { ThemeProvider } from '@gravity-ui/uikit';

import { App } from './App';
import { I18nProvider, useI18n } from './i18n';

// ThemeProvider forwards `lang` to uikit components (built-in texts: en / ru).
function Providers({ children }: React.PropsWithChildren) {
  const { lang } = useI18n();
  return (
    <ThemeProvider theme="light" lang={lang}>
      {children}
    </ThemeProvider>
  );
}

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <I18nProvider>
      <Providers>
        <App />
      </Providers>
    </I18nProvider>
  </React.StrictMode>,
);
EOF
cat > src/App.tsx <<'EOF'
import { ClipboardButton, Flex, SegmentedRadioGroup, Text } from '@gravity-ui/uikit';

import { LANGS, useI18n } from './i18n';
import type { AppLang } from './i18n';

export function App() {
  const { lang, setLang, t } = useI18n();

  return (
    <Flex direction="column" gap={4} style={{ padding: 24, maxWidth: 520 }}>
      <Text variant="header-1">{t('title')}</Text>
      <Text variant="body-2" color="secondary">
        {t('description')}
      </Text>

      <SegmentedRadioGroup<AppLang>
        aria-label={t('switcher_label')}
        value={lang}
        onUpdate={setLang}
      >
        {LANGS.map((code) => (
          <SegmentedRadioGroup.Option key={code} value={code}>
            {t(code === 'en' ? 'language_en' : 'language_ru')}
          </SegmentedRadioGroup.Option>
        ))}
      </SegmentedRadioGroup>

      <Text variant="body-2">
        {t('current', { language: t(lang === 'en' ? 'language_en' : 'language_ru') })}
      </Text>

      <Text variant="body-2" color="secondary">
        {t('copy_hint')}
      </Text>
      <div>
        <ClipboardButton text={t('title')} size="m" />
      </div>
    </Flex>
  );
}
EOF
